-- cpl_memory rows, second set, for SkyTystie (S705): Sam's five statements of 2026-11-22 (verified, verified_by Sam)
-- and two decisions of the session (proposed). Applied with execute_sql. ROLLBACK: the _rollback file beside it.
on conflict (slug) do nothing;
select id, 'SkyTystie (S705)', 'create', 'S705 (2026-11-22)', to_jsonb(m)
from public.cpl_memory m where m.author = 'SkyTystie (S705)'
  and not exists (select 1 from public.cpl_memory_log l where l.memory_id = m.id and l.action = 'create');
select slug, status from public.cpl_memory where author = 'SkyTystie (S705)' order by slug;
