insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('r-sidebars-resize-and-frozen-top-sam-2026-11-22','decision','Every sidebar resizes and keeps its top row frozen','Sam, 2026-11-22, in session (S705): "the sidebar needs to be adjustable width and the top row, including the close button, should be frozen to the tope as you scroll--this is a rule to apply to all side bars--when scrolling down, user loses view of close button and with the two vertical scroll bars, it can be difficult to navigate up to see close."',array['commons','subjects','ui','presentation'],'verified','Sam in session, 2026-11-22 (S705)','Sam',now(),'SkyTystie (S705)','2026-11-22'),
('r-subjects-move-courses-sam-2026-11-22','decision','Move one course or a group to another common subject code from the Subjects panel','Sam, 2026-11-22, in session (S705), on Cerritos AED: "related to it is the list of ELEC courses that at one point got defined as AED, which is an error. I have no way to fix that error on this screen or sidebar and need a simple way to do that for 1 or a groups of courses that need to be reassigned."',array['commons','subjects','m-id'],'verified','Sam in session, 2026-11-22 (S705)','Sam',now(),'SkyTystie (S705)','2026-11-22'),
('r-subjects-columns-sort-resize-sam-2026-11-22','decision','Subjects columns sort and resize, as the Commons views do','Sam, 2026-11-22, in session (S705): "The columns on subjects tab need to be sortable and resizable--following our formatting norms for commons views".',array['commons','subjects','ui'],'verified','Sam in session, 2026-11-22 (S705)','Sam',now(),'SkyTystie (S705)','2026-11-22'),
('r-college-department-list-is-a-title-source-sam-2026-11-22','decision','A college''s department list titles its local subject codes (Cerritos)','Sam, 2026-11-22 (S705), pasting Cerritos''s schedule list (secure.cerritos.edu/schedule/index.cgi): "use this list and mark them done. add this to our procedures with a note about cerritos departments defining their local subject titles." AED=Adult Education. Filed kb/reference/college_department_lists/cerritos.json; playbook-local-subject-title-sources.',array['commons','subjects','catalogs'],'verified','Sam in session, 2026-11-22 (S705)','Sam',now(),'SkyTystie (S705)','2026-11-22'),
('r-subject-title-source-link-sam-2026-11-22','decision','A subject decision carries the link it came from, testable before Save','Sam, 2026-11-22 (S705), after editing AED in the sidebar: "I wanted to add the link and test it like I can for catalog collection process, but need that ability."',array['commons','subjects'],'verified','Sam in session, 2026-11-22 (S705)','Sam',now(),'SkyTystie (S705)','2026-11-22'),
('d-course-move-field-crs-key-s705','decision','A course move is one kb_curation row, CRS:<college>|<code>|<number>','S705: the Subjects panel''s course move writes field course_subject_decision, course_id CRS:<college>|<local code>|<course number>, value common_code, from_mid, title, band, under the reviewer''s email (DR-25). It records the decision; the M-ID moves at a re-mint under the playbook. Another person''s move is held. Sky''s call, Sam''s to revise.',array['commons','subjects','m-id'],'proposed','PR #3687; tests/commons_subjects_tools.test.js',null,null,'SkyTystie (S705)','2026-11-22'),
('d-source-link-on-form-before-handover-s705','decision','The source link lives on the Edit form; the hand-over reader comes later','S705: the Edit form takes a source link saved in the decision as source_url, with Open the link to check it in a new tab. The hand-over box''s server reader needs a new dataset in commons_handover (a migration) and its handover-try-link answers 503, so it is the next step. Sky''s call, Sam''s to revise.',array['commons','subjects'],'proposed','PR #3687',null,null,'SkyTystie (S705)','2026-11-22')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
